effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 tam = vec2(textureSize(inputImg, 0));
    float tamDaCelula = max(dotSize, 1.0);
    vec2 grade = tam / tamDaCelula;

    vec2 escalado = acScreenNorm * grade;
    vec2 i = floor(escalado);
    vec2 f = fract(escalado) - 0.5;

    // UV do centro da célula (lê a imagem UMA vez por célula, não por pixel).
    vec2 uvDoCentro = (i + 0.5) / grade;
    vec4 corDaCelula = texture(inputImg, uvDoCentro);

    // O raio cresce com a luma: claro = ponto grande.
    float r = luma(corDaCelula.rgb) * radius * 0.5;

    // Desenha o ponto com anti-serrilhagem suave.
    float d = length(f);
    float ponto = 1.0 - smoothstep(r - max(softness * 0.25, 1e-4), r + max(softness * 0.25, 1e-4), d);

    // Fundo: papel com opacidade controlada; o original passa onde o papel não cobre.
    vec4 fundo = mix(original, vec4(paperColor.rgb, 1.0), paperAlpha * paperColor.a);

    vec4 saida = mix(fundo, vec4(corDaCelula.rgb, 1.0), ponto);

    fragColor = saida;
}
